Để làm tròn kết quả, mình sẽ thêm một bước kiểm tra điều kiện (validation) ngay trong hàm khởi tạo `__init__`. Nếu người dùng nhập số âm hoặc bằng 0, chương trình sẽ thông báo lỗi thay vì tính ra kết quả vô lý.

```python
import math

class HinhTru:
    def __init__(self, r, h):
        if r <= 0 or h <= 0:
            raise ValueError("Bán kính và chiều cao phải là số dương!")
        self.r = r
        self.h = h

    def tinh_dien_tich(self):
        return 2 * math.pi * self.r * (self.r + self.h)

    def tinh_the_tich(self):
        # Công thức: V = pi * r² * h
        return math.pi * (self.r**2) * self.h

# Sử dụng class
hinh_tru = HinhTru(5, 10)
print(f"Diện tích: {hinh_tru.tinh_dien_tich():.2f}")
print(f"Thể tích: {hinh_tru.tinh_the_tich():.2f}")
```
